// Conformance streams for decoder features no production encoder writes, generated by the managed encoder's
// test-only hooks: POC types 0 and 1 with non-reference pictures, frame_num gaps across the frame_num wrap,
// long-term references with every memory management operation and list modification, forced I_PCM, arbitrary slice
// order and redundant slices (Baseline), and explicit weighted bi-prediction from B slices synthesized here. The
// requirements were fixed before the first run: the managed decoder and FFmpeg (single-threaded) must each output
// exactly the encoder's reconstruction, so they agree bit-exactly. FFmpeg deviates in three places, each reported
// and narrowed to its cause while the managed decoder stays held to the full stream: it does not implement arbitrary
// slice order (reported only); a redundant IDR slice makes it drop all references (it is held to the stream without
// the redundant IDR slices); and a POC type 2 gap longer than max_num_ref_frames across the frame_num wrap loses
// output pictures (every picture it outputs must still be exact, and the same gaps with POC type 0 are held in full).
// Weighted B pictures (all B_Skip, spatial direct, zero motion, deblocking off) are held to an independent oracle:
// the explicit weighted sample prediction of 8.4.2.3 applied to the two references' reconstructions.

using System.Globalization;
using RTSP.IngestService.Media.Codecs.Video.H264.Encoder;
using RTSP.IngestService.Tests.Infrastructure;

namespace RTSP.IngestService.Tests.Media.Codecs.H264;

/// <summary>Hook-generated conformance streams decode identically in the managed decoder and FFmpeg.</summary>
public sealed class H264EncoderConformanceStreamTests
{
    /// <summary>log2_max_pic_order_cnt_lsb of the encoder's POC type 0 streams.</summary>
    private const int Log2MaxPocLsb = 8;

    /// <summary>luma_log2_weight_denom of the synthesized B slices.</summary>
    private const int LumaDenom = 5;

    /// <summary>chroma_log2_weight_denom of the synthesized B slices.</summary>
    private const int ChromaDenom = 4;

    /// <summary>Non-reference pictures under each POC type keep their output order.</summary>
    /// <param name="pocType">pic_order_cnt_type.</param>
    /// <returns>A task.</returns>
    [Theory]
    [InlineData(0)]
    [InlineData(1)]
    [InlineData(2)]
    public async Task PocTypesWithNonReferencePictures(int pocType)
    {
        var hooks = new H264EncoderTestHooks
        {
            PocType = pocType,
            Control = i => new H264PictureControl { NonReference = pocType == 0 ? i % 4 is 1 or 2 : i % 3 == 2 },
        };
        await AssertConformsAsync(Encode(hooks, 30, references: 2));
    }

    /// <summary>frame_num gaps (non-existing frames in the lists) across several frame_num wraps, POC type 2.</summary>
    /// <returns>A task.</returns>
    [Fact]
    public async Task FrameNumGaps()
    {
        var frames = Encode(GapHooks(pocType: 2), 30, references: 3);
        H264EncoderTestSupport.AssertMatchesReconstruction(frames, H264EncoderTestSupport.DecodeManagedAnnexB(frames));
        var raw = await DecodeWithFfmpegAsync(FfmpegTool.Require(), H264EncoderTestSupport.Concatenate(frames), allowFailure: false);
        var omitted = AssertRawSubsequence(frames, raw!);
        TestContext.Current.TestOutputHelper?.WriteLine($"FFmpeg omitted pictures: [{string.Join(", ", omitted)}]");
    }

    /// <summary>The same frame_num gaps with explicit POC (type 0).</summary>
    /// <returns>A task.</returns>
    [Fact]
    public async Task FrameNumGapsWithExplicitPoc() => await AssertConformsAsync(Encode(GapHooks(pocType: 0), 30, references: 3));

    /// <summary>A long-term IDR, MMCO 1 to 6 and list modification of short- and long-term pictures.</summary>
    /// <returns>A task.</returns>
    [Fact]
    public async Task LongTermReferencesAndMemoryManagement()
    {
        var controls = new Dictionary<long, H264PictureControl>
        {
            [0] = new() { LongTermReference = true },
            [3] = new() { Mmcos = [new(1, 1), new(4, 2), new(3, 0, 1)] },
            [5] = new() { ListModifications = [new(2, 0)] },
            [6] = new() { ListModifications = [new(0, 0), new(2, 1)] },
            [7] = new() { Mmcos = [new(6, 0, 0)] },
            [8] = new() { Mmcos = [new(2, 1)] },
            [10] = new() { Mmcos = [new(5)] },
            [12] = new() { Mmcos = [new(4, 0)] },
            [14] = new() { Mmcos = [new(1, 2), new(4, 1), new(6, 0, 0)] },
            [15] = new() { ListModifications = [new(2, 0), new(0, 1)] },
        };
        var hooks = new H264EncoderTestHooks { PocType = 0, Control = i => controls.GetValueOrDefault(i) };
        await AssertConformsAsync(Encode(hooks, 22, references: 3));
    }

    /// <summary>Forced I_PCM macroblocks in IDR and P pictures.</summary>
    /// <returns>A task.</returns>
    [Fact]
    public async Task ForcedPcm()
    {
        var hooks = new H264EncoderTestHooks { Control = static i => new H264PictureControl { ForcePcm = mb => ((mb * 7) + i) % 4 == 0 } };
        var frames = Encode(hooks, 8, references: 1);
        Assert.All(frames, static f => Assert.True(f.Statistics.PcmMacroblocks > 0));
        await AssertConformsAsync(frames);
    }

    /// <summary>Redundant slices (Baseline) are discarded and the primary picture decoded.</summary>
    /// <returns>A task.</returns>
    [Fact]
    public async Task RedundantSlices()
    {
        var hooks = new H264EncoderTestHooks { ProfileIdc = 66, RedundantSlices = true };
        var frames = Encode(hooks, 12, references: 1, slices: 2);
        H264EncoderTestSupport.AssertMatchesReconstruction(frames, H264EncoderTestSupport.DecodeManagedAnnexB(frames));
        var ffmpeg = FfmpegTool.Require();
        var raw = await DecodeWithFfmpegAsync(ffmpeg, H264EncoderTestSupport.Concatenate(frames), allowFailure: true);
        TestContext.Current.TestOutputHelper?.WriteLine("With redundant IDR slices: " + Describe(frames, raw));

        // FFmpeg drops every reference at each IDR NAL unit, including a redundant one after the primary IDR picture.
        var primaryIdr = frames.Select(static f => f with { Data = f.IsKeyframe ? WithoutRedundantSlices(f.Data) : f.Data }).ToList();
        await AssertConformsAsync(primaryIdr);
    }

    /// <summary>Slices in reverse order (Baseline ASO) decode to the reconstruction in the managed decoder.</summary>
    /// <returns>A task.</returns>
    [Fact]
    public async Task ArbitrarySliceOrder()
    {
        var hooks = new H264EncoderTestHooks { ProfileIdc = 66, ReverseSliceOrder = true };
        var frames = Encode(hooks, 12, references: 1, slices: 3);
        H264EncoderTestSupport.AssertMatchesReconstruction(frames, H264EncoderTestSupport.DecodeManagedAnnexB(frames));
        if (FfmpegTool.Path is { } ffmpeg)
        {
            var raw = await DecodeWithFfmpegAsync(ffmpeg, H264EncoderTestSupport.Concatenate(frames), allowFailure: true);
            TestContext.Current.TestOutputHelper?.WriteLine(Describe(frames, raw));
        }
    }

    /// <summary>Explicit weighted bi-prediction from synthesized B slices between the encoder's P pictures.</summary>
    /// <returns>A task.</returns>
    [Fact]
    public async Task ExplicitWeightedBiPrediction()
    {
        const int width = 128, height = 80, count = 12;
        var hooks = new H264EncoderTestHooks { PocType = 0, WeightedBipredIdc = 1, MaxNumReorderFrames = 1 };
        var options = H264EncoderTestSupport.Options(width, height) with { Format = H264OutputFormat.AnnexB, MaxReferenceFrames = 2 };
        using var encoder = new H264Encoder(options, hooks);
        var units = new List<H264EncodedAccessUnit>();
        var coded = new List<EncodedFrame>();
        var display = new List<EncodedFrame>();
        EncodedFrame? previous = null;
        for (var k = 0; k <= count; k++)
        {
            using var frame = H264EncoderTestSupport.CreateFrame(SyntheticPattern.Motion, width, height, 2 * k);
            encoder.Encode(frame, units, cancellationToken: TestContext.Current.CancellationToken);
            var current = H264EncoderTestSupport.Take(encoder, units);
            Assert.Equal(2L * k * 3600, current.Timestamp);
            coded.Add(current);
            if (previous is not null)
            {
                var weights = Weights.For(k);
                var b = new EncodedFrame(
                    SynthesizeB(frameNum: k + 1, pocLsb: (2 * k) - 1, mbCount: (width / 16) * (height / 16), weights),
                    ((2L * k) - 1) * 3600,
                    false,
                    Blend(previous.Reconstruction, current.Reconstruction, width, height, weights),
                    current.Statistics);
                coded.Add(b);
                display.Add(b);
            }

            display.Add(current);
            previous = current;
        }

        H264EncoderTestSupport.AssertMatchesReconstruction(display, H264EncoderTestSupport.DecodeManagedAnnexB(coded));
        var raw = await DecodeWithFfmpegAsync(FfmpegTool.Require(), H264EncoderTestSupport.Concatenate(coded), allowFailure: false);
        AssertRawMatches(display, raw!);
    }

    /// <summary>Encodes Annex B frames of the motion pattern with hooks.</summary>
    /// <param name="hooks">The hooks.</param>
    /// <param name="count">The frame count.</param>
    /// <param name="references">max_num_ref_frames.</param>
    /// <param name="slices">Slices per picture.</param>
    /// <returns>The frames.</returns>
    private static List<EncodedFrame> Encode(H264EncoderTestHooks hooks, int count, int references, int slices = 1)
    {
        var options = H264EncoderTestSupport.Options(96, 64) with
        {
            Format = H264OutputFormat.AnnexB,
            MaxReferenceFrames = references,
            SlicesPerPicture = slices,
        };
        using var encoder = new H264Encoder(options, hooks);
        return H264EncoderTestSupport.EncodeAll(encoder, SyntheticPattern.Motion, count);
    }

    /// <summary>Asserts that the managed decoder and FFmpeg both output exactly the reconstruction.</summary>
    /// <param name="frames">The frames, Annex B.</param>
    /// <returns>A task.</returns>
    private static async Task AssertConformsAsync(List<EncodedFrame> frames)
    {
        H264EncoderTestSupport.AssertMatchesReconstruction(frames, H264EncoderTestSupport.DecodeManagedAnnexB(frames));
        var raw = await DecodeWithFfmpegAsync(FfmpegTool.Require(), H264EncoderTestSupport.Concatenate(frames), allowFailure: false);
        AssertRawMatches(frames, raw!);
    }

    /// <summary>Returns hooks with frame_num gaps of 2, 5, 1 and 13 (MaxFrameNum 16) and two non-reference pictures.</summary>
    /// <param name="pocType">pic_order_cnt_type.</param>
    /// <returns>The hooks.</returns>
    private static H264EncoderTestHooks GapHooks(int pocType) => new()
    {
        GapsAllowed = true,
        Log2MaxFrameNum = 4,
        PocType = pocType,
        Control = static i => new H264PictureControl
        {
            FrameNumGap = i switch { 3 => 2, 8 => 5, 14 => 1, 20 => 13, _ => 0 },
            NonReference = i is 14 or 25,
        },
    };

    /// <summary>Asserts that every frame FFmpeg outputs is exactly the reconstruction of a picture, in order.</summary>
    /// <param name="frames">The expected frames in output order.</param>
    /// <param name="raw">The rawvideo bytes.</param>
    /// <returns>The indices of the pictures FFmpeg did not output.</returns>
    private static List<int> AssertRawSubsequence(List<EncodedFrame> frames, byte[] raw)
    {
        var size = frames[0].Reconstruction.Length;
        Assert.Equal(0, raw.Length % size);
        var omitted = new List<int>();
        var next = 0;
        for (var j = 0; j < raw.Length / size; j++)
        {
            var actual = raw.AsSpan(j * size, size);
            while (next < frames.Count && !actual.SequenceEqual(frames[next].Reconstruction))
            {
                omitted.Add(next++);
            }

            Assert.True(next < frames.Count, string.Create(CultureInfo.InvariantCulture, $"FFmpeg output frame {j} is not the reconstruction of any later picture."));
            next++;
        }

        omitted.AddRange(Enumerable.Range(next, frames.Count - next));
        return omitted;
    }

    /// <summary>Removes the redundant coded picture, which is the second half of the slices (one copy per primary slice).</summary>
    /// <param name="accessUnit">The Annex B access unit.</param>
    /// <returns>The access unit with the primary picture only.</returns>
    private static byte[] WithoutRedundantSlices(byte[] accessUnit)
    {
        var nals = H264TestSupport.SplitNalUnits(accessUnit);
        var slices = nals.Count(static n => (n[0] & 0x1F) is 1 or 5);
        return H264TestSupport.Join(nals.Take(nals.Count - (slices / 2)));
    }

    /// <summary>Asserts that FFmpeg's raw output is exactly the expected frames.</summary>
    /// <param name="frames">The expected frames in output order.</param>
    /// <param name="raw">The rawvideo bytes.</param>
    private static void AssertRawMatches(List<EncodedFrame> frames, byte[] raw)
    {
        var size = frames[0].Reconstruction.Length;
        Assert.Equal(frames.Count * size, raw.Length);
        for (var i = 0; i < frames.Count; i++)
        {
            var actual = raw.AsSpan(i * size, size);
            if (!actual.SequenceEqual(frames[i].Reconstruction))
            {
                Assert.Fail(string.Create(CultureInfo.InvariantCulture, $"Frame {i}: FFmpeg differs at byte {actual.CommonPrefixLength(frames[i].Reconstruction)} of {size}."));
            }
        }
    }

    /// <summary>Describes how FFmpeg's output compares with the expected frames.</summary>
    /// <param name="frames">The expected frames.</param>
    /// <param name="raw">The rawvideo bytes, or null when FFmpeg failed.</param>
    /// <returns>The description.</returns>
    private static string Describe(List<EncodedFrame> frames, byte[]? raw)
    {
        if (raw is null)
        {
            return "FFmpeg (informational): decoding failed.";
        }

        var size = frames[0].Reconstruction.Length;
        var output = raw.Length / size;
        var exact = Enumerable.Range(0, Math.Min(output, frames.Count)).Count(i => raw.AsSpan(i * size, size).SequenceEqual(frames[i].Reconstruction));
        return string.Create(CultureInfo.InvariantCulture, $"FFmpeg (informational): {output} frames output for {frames.Count} coded, {exact} identical to the reconstruction.");
    }

    /// <summary>Decodes an Annex B stream with FFmpeg to yuv420p rawvideo.</summary>
    /// <param name="ffmpeg">The FFmpeg executable.</param>
    /// <param name="stream">The stream.</param>
    /// <param name="allowFailure">Whether a failing FFmpeg returns null instead of failing the test.</param>
    /// <returns>The rawvideo bytes, or null.</returns>
    private static async Task<byte[]?> DecodeWithFfmpegAsync(string ffmpeg, byte[] stream, bool allowFailure)
    {
        var directory = Directory.CreateTempSubdirectory("h264-conformance-");
        try
        {
            var input = Path.Combine(directory.FullName, "stream.h264");
            var raw = Path.Combine(directory.FullName, "stream.yuv");
            await File.WriteAllBytesAsync(input, stream, TestContext.Current.CancellationToken);
            string[] arguments = ["-hide_banner", "-loglevel", "error", "-nostdin", "-y", "-threads", "1", "-f", "h264", "-i", input, "-fps_mode", "passthrough", "-f", "rawvideo", "-pix_fmt", "yuv420p", raw];
            if (allowFailure)
            {
                try
                {
                    await H264EncoderTestSupport.RunAsync(ffmpeg, arguments);
                }
                catch (Xunit.Sdk.XunitException)
                {
                    return null;
                }
            }
            else
            {
                await H264EncoderTestSupport.RunAsync(ffmpeg, arguments);
            }

            return await File.ReadAllBytesAsync(raw, TestContext.Current.CancellationToken);
        }
        finally
        {
            directory.Delete(true);
        }
    }

    /// <summary>Writes a non-reference B access unit whose single slice skips every macroblock.</summary>
    /// <param name="frameNum">frame_num: PrevRefFrameNum + 1.</param>
    /// <param name="pocLsb">pic_order_cnt_lsb, between the two references.</param>
    /// <param name="mbCount">The macroblock count.</param>
    /// <param name="weights">The explicit weights.</param>
    /// <returns>The Annex B access unit.</returns>
    private static byte[] SynthesizeB(int frameNum, int pocLsb, int mbCount, Weights weights)
    {
        using var w = new H264BitWriter(64, 1024);
        w.WriteUe(0);
        w.WriteUe(6);
        w.WriteUe(0);
        w.Write((uint)frameNum, 8);
        w.Write((uint)pocLsb, Log2MaxPocLsb);
        w.WriteBit(true);
        w.WriteBit(true);
        w.WriteUe(0);
        w.WriteUe(0);
        w.WriteBit(false);
        w.WriteBit(false);
        w.WriteUe(LumaDenom);
        w.WriteUe(ChromaDenom);
        foreach (var list in (ReadOnlySpan<int>)[0, 1])
        {
            w.WriteBit(true);
            w.WriteSe(weights.Weight[0][list]);
            w.WriteSe(weights.Offset[0][list]);
            w.WriteBit(true);
            for (var plane = 1; plane < 3; plane++)
            {
                w.WriteSe(weights.Weight[plane][list]);
                w.WriteSe(weights.Offset[plane][list]);
            }
        }

        w.WriteSe(0);
        w.WriteUe(1);
        w.WriteUe(mbCount);
        w.WriteTrailingBits();
        return H264TestSupport.Join([H264ParameterSetWriter.Nal(0, 1, w.Written)]);
    }

    /// <summary>The explicit weighted bi-prediction of 8.4.2.3 (8-301) with zero motion, per plane.</summary>
    /// <param name="first">The list 0 reference, packed.</param>
    /// <param name="second">The list 1 reference, packed.</param>
    /// <param name="width">The width.</param>
    /// <param name="height">The height.</param>
    /// <param name="weights">The weights.</param>
    /// <returns>The predicted picture, packed.</returns>
    private static byte[] Blend(byte[] first, byte[] second, int width, int height, Weights weights)
    {
        var result = new byte[first.Length];
        var luma = width * height;
        for (var i = 0; i < result.Length; i++)
        {
            var plane = i < luma ? 0 : i < luma + (luma / 4) ? 1 : 2;
            var logWd = plane == 0 ? LumaDenom : ChromaDenom;
            var (w0, w1) = (weights.Weight[plane][0], weights.Weight[plane][1]);
            var (o0, o1) = (weights.Offset[plane][0], weights.Offset[plane][1]);
            var value = (((first[i] * w0) + (second[i] * w1) + (1 << logWd)) >> (logWd + 1)) + ((o0 + o1 + 1) >> 1);
            result[i] = (byte)Math.Clamp(value, 0, 255);
        }

        return result;
    }

    /// <summary>Explicit weights and offsets by plane (Y, Cb, Cr) and list.</summary>
    /// <param name="Weight">The weights.</param>
    /// <param name="Offset">The offsets.</param>
    private sealed record Weights(int[][] Weight, int[][] Offset)
    {
        /// <summary>Returns the weights of the B picture before P picture <paramref name="k"/>, including negative weights and offsets.</summary>
        /// <param name="k">The P picture index.</param>
        /// <returns>The weights.</returns>
        public static Weights For(int k) => new(
            [[24 + k, 40 - (2 * k)], [10, 6 + (k % 3)], [20, -6]],
            [[k - 4, 3], [2, -1], [-3, 5 + k]]);
    }
}
